// --- In Widget.h ---
#include <memory>

class Widget {
public:
    Widget();
    ~Widget(); // Destructor must be declared

    // Support for move operations is crucial
    Widget(Widget&&) noexcept;
    Widget& operator=(Widget&&) noexcept;

    // Copy operations would require deep copies and are often deleted or implemented manually
    Widget(const Widget&) = delete;
    Widget& operator=(const Widget&) = delete;

private:
    struct Impl; // Forward-declare the implementation struct
    std::unique_ptr<Impl> pImpl; // Use unique_ptr to manage lifetime
};


// --- In Widget.cpp ---
#include "Widget.h"
#include <string>
#include <vector>

// Full definition of the implementation struct is only here
struct Widget::Impl {
    std::string name;
    std::vector<int> data;
};

// Constructor definition initializes the unique_ptr
Widget::Widget() 
    : pImpl(std::make_unique<Impl>()) 
{}

// Destructor definition is here, where Impl is a complete type
// This allows unique_ptr's default deleter to compile correctly.
Widget::~Widget() = default;

// Move operations are also defined here
Widget::Widget(Widget&&) noexcept = default;
Widget& Widget::operator=(Widget&&) noexcept = default;
